def _ui_search_terms(value: Any) -> set[str]:
    text = str(value or "").lower().replace("ё", "е")
    tokens = set(re.findall(r"[a-zа-яіїє0-9]{3,}", text, re.I))
    stop = {"как", "куда", "где", "что", "мне", "тебя", "твой", "твое", "твоем", "это", "для", "или", "and", "the", "with", "where", "what", "how", "you", "your", "into", "from", "кнопка", "кнопки", "элемент", "элементы", "покажи", "показать", "обозначает", "обозначать", "сказать", "объясни", "объяснить"}
    tokens.difference_update(stop)
    synonyms = {
        "премиум": {"premium", "подписка", "тариф", "оплата", "план"},
        "premium": {"премиум", "подписка", "тариф", "оплата", "план"},
        "подключить": {"активировать", "оформить", "купить", "оплатить", "premium", "премиум"},
        "активировать": {"подключить", "оформить", "купить", "оплатить"},
        "профиль": {"settings", "настройки", "account", "кабинет"},
        "настройки": {"профиль", "settings", "account"},
        "сообщество": {"community", "space", "друзья"},
        "справка": {"help", "information", "support"},
        "скрепка": {"вложение", "файл", "фото", "attachment"},
        "язык": {"языка", "language", "локаль", "перевод", "выбор", "выбрать"},
        "языка": {"язык", "language", "локаль", "перевод", "выбор", "выбрать"},
        "график": {"графике", "graph", "chart", "масштаб", "ракурс"},
        "графике": {"график", "graph", "chart", "масштаб", "ракурс"},
        "диаграмма": {"diagram", "svg", "схема"},
        "увеличить": {"zoom", "приблизить", "scale", "масштаб"},
        "уменьшить": {"zoom", "отдалить", "scale", "масштаб"},
        "поддержка": {"поддержку", "поддержке", "support", "ticket", "обращение"},
        "поддержку": {"поддержка", "поддержке", "support", "ticket", "обращение"},
        "поддержке": {"поддержка", "поддержку", "support", "ticket", "обращение"},
        "видеокошелек": {"video", "wallet", "кредиты", "пополнение"},
        "видеокошелька": {"video", "wallet", "кредиты", "пополнение"},
        "кошелек": {"кошелька", "wallet", "video", "кредиты"},
        "пополнить": {"пополнение", "buy", "purchase", "credits", "wallet"},
        "история": {"историю", "history", "разговоры", "диалоги"},
        "историю": {"история", "history", "разговоры", "диалоги"},
        "удалить": {"удаление", "delete"},
        "аккаунт": {"account", "профиль", "удаление"},
    }
    expanded = set(tokens)
    for token in tuple(tokens):
        expanded.update(synonyms.get(token, set()))
    return expanded


def search_april_ui(query: str, limit: int = 4) -> Dict[str, Any]:
    """Resolve exact April screen/control first, then use conservative lexical fallback.

    Older versions ranked every function by broad token overlap, so a query about
    changing the interface language could return unrelated chat/community controls.
    This version puts the source-specific operation resolver first and only keeps
    lexical matches that are materially related to the selected route.
    """
    q = str(query or "").strip()[:1200]
    terms = _ui_search_terms(q)
    plan_query = _is_april_premium_navigation_query(q)
    wallet_query = _is_video_wallet_purchase_query(q)
    area_scores = _semantic_site_area_scores(q)
    area_ids = [area_id for score, area_id in area_scores if score >= 2.0]
    if wallet_query:
        area_ids = ["settings"]
    elif not area_ids:
        area_ids = ["chat"] if re.search(r"(?:april|април|чат|кнопк|скрепк|метла|микрофон)", q, re.I) else []

    # Typed semantics, when available through an explicit local target, are stronger
    # than word overlap. The compatibility resolver returns only known catalogue IDs.
    candidate_ids = _site_focused_function_candidates(q, area_ids)
    unresolved_troubleshooting = _is_ui_troubleshooting_query(q) and not candidate_ids
    if unresolved_troubleshooting:
        area_ids = []
    if not candidate_ids and _is_video_help_query(q):
        candidate_ids = ["chat_attach_file", "chat_attachment_picker_controls", "chat_text_send"]
    if candidate_ids:
        candidate_set = set(candidate_ids)
        focused_areas = []
        for item in APRIL_UI_FUNCTION_CATALOG.get("functions", []):
            if not isinstance(item, dict) or str(item.get("id") or "") not in candidate_set:
                continue
            for area_id in item.get("areas", []) if isinstance(item.get("areas"), list) else []:
                if area_id not in focused_areas:
                    focused_areas.append(area_id)
        if focused_areas:
            area_ids = focused_areas

    screen_rows = []
    for screen in APRIL_UI_SCREEN_EVIDENCE.get("screens", []):
        screen_text = " ".join([
            str(screen.get("id", "")), str(screen.get("title", "")), str(screen.get("route", "")),
            " ".join(screen.get("aliases", [])), " ".join(screen.get("visible_labels", [])),
            str(screen.get("position", "")),
        ])
        screen_terms = _ui_search_terms(screen_text)
        score = 2 * len(terms & screen_terms)
        if plan_query and screen.get("id") == "profile_plan":
            score += 100
        if wallet_query and screen.get("id") == "profile_video_wallet":
            score += 150
        if area_ids and screen.get("route"):
            route_by_area = {
                "chat": "/", "attachments": "/", "image-controls": "/", "graph-controls": "/",
                "response-feedback": "/", "settings": "/settings", "plans": "/settings",
                "history": "/history", "space": "/space", "direct": "/space/direct/[friendId]",
                "support": "/insights?room=support", "guide": "/aprill", "help-center": "/aprill",
            }
            if any(route_by_area.get(area_id) == screen.get("route") for area_id in area_ids):
                score += 8
        if score:
            screen_rows.append((score, screen))
    screen_rows.sort(key=lambda row: row[0], reverse=True)
    # A video-wallet purchase is a distinct checkout flow, not a subscription
    # package action. Do not leak the generic CURRENT PLAN screen into its
    # focused evidence set merely because both happen to live under /settings.
    if wallet_query:
        screen_rows = [row for row in screen_rows if row[1].get("id") == "profile_video_wallet"]

    function_rows = []
    for item in APRIL_UI_FUNCTION_CATALOG.get("functions", []):
        if unresolved_troubleshooting:
            break
        if not isinstance(item, dict):
            continue
        item_id = str(item.get("id") or "")
        fields = [item.get(key, "") for key in ("screen", "entry", "position", "control", "does", "availability", "limits")]
        fields.extend(item.get("how_to_use", []) if isinstance(item.get("how_to_use"), list) else [])
        item_terms = _ui_search_terms(" ".join(map(str, fields)))
        overlap = len(terms & item_terms)
        score = overlap
        if item_id in candidate_ids:
            score += 1000 - candidate_ids.index(item_id)
        if area_ids and any(area_id in (item.get("areas") or []) for area_id in area_ids):
            score += 5
        if plan_query and item_id in {"settings_plan_payment", "settings_premium_packages"}:
            score += 500
        if wallet_query and item_id == "settings_video_wallet":
            score += 600
        # Exclude low-signal matches instead of filling the result with unrelated controls.
        if score >= (900 if candidate_ids else 3):
            function_rows.append((score, item))
    function_rows.sort(key=lambda row: row[0], reverse=True)

    chosen_screens = []
    for _score, screen in screen_rows[:2]:
        chosen_screens.append({
            "id": screen.get("id"), "route": screen.get("route"), "title": screen.get("title"),
            "position": screen.get("position"), "visible_labels": list(screen.get("visible_labels", [])),
            "controls": list(screen.get("controls", []))[:8],
            **({"trial_evidence": screen.get("trial_evidence")} if screen.get("trial_evidence") else {}),
        })

    chosen_functions = []
    seen_ids = set()
    max_functions = max(1, min(int(limit or 4), 6))
    for _score, item in function_rows:
        item_id = str(item.get("id") or "")
        if item_id in seen_ids:
            continue
        seen_ids.add(item_id)
        chosen_functions.append({
            "id": item_id, "screen": item.get("screen"), "entry": item.get("entry"),
            "position": item.get("position"), "control": item.get("control"),
            "purpose": item.get("does"), "steps": list(item.get("how_to_use", []))[:7],
            "result": item.get("result"), "availability": item.get("availability"),
            "limits": item.get("limits"),
        })
        if len(chosen_functions) >= max_functions:
            break

    return {
        "schema": "april.ui_search_result.v2", "query": q,
        "domain": "april_ui", "focused_intent": "video_wallet_purchase" if wallet_query else ("premium_plan_navigation" if plan_query else "screen_and_control_lookup"),
        "screen_matches": chosen_screens, "control_matches": chosen_functions,
        "candidate_function_ids": candidate_ids[:8], "matched_area_ids": area_ids[:8],
        "troubleshooting": _is_ui_troubleshooting_query(q),
        "evidence_source": APRIL_UI_SCREEN_EVIDENCE.get("source", ""),
        "evidence_limits": APRIL_UI_SCREEN_EVIDENCE.get("limits", ""),
        "source_screen_registry": APRIL_UI_SCREEN_REGISTRY.get("source", ""),
        "visual_evidence_mode": APRIL_UI_SCREEN_REGISTRY.get("visual_evidence_mode", ""),
    }


def _select_ui_screen_registry(query: str, site_map: Dict[str, Any]) -> Dict[str, Any]:
    """Return only screen records required by this help request (or all for overview)."""
    areas = site_map.get("areas") if isinstance(site_map, dict) else []
    selected_area_ids = {str(item.get("id")) for item in areas if isinstance(item, dict)}
    full = bool(site_map.get("full_interface_overview")) if isinstance(site_map, dict) else False
    route_by_area = {
        "chat": {"/"}, "attachments": {"/"}, "image-controls": {"/"}, "graph-controls": {"/"},
        "response-feedback": {"/"}, "settings": {"/settings"}, "plans": {"/settings"},
        "history": {"/history"}, "space": {"/space"}, "direct": {"/space/direct/[friendId]"},
        "support": {"/insights?room=support"}, "guide": {"/aprill"}, "help-center": {"/aprill"},
        "how-to-use": {"/aprill"}, "deletion": {"/account-deletion"}, "privacy": {"/privacy-policy"},
        "terms": {"/terms-of-service"}, "memory": {"/memory"}, "tools": {"/tools"},
    }
    routes = set()
    for area_id in selected_area_ids:
        routes.update(route_by_area.get(area_id, set()))
    if _is_video_help_query(query):
        routes.add("/")
    unresolved_ui_control = bool(site_map.get("unresolved_ui_control")) if isinstance(site_map, dict) else False
    if unresolved_ui_control:
        routes.clear()
    renderer_query_patterns = {
        "render_gallery": r"(?:изображен\w*|картинк\w*|галере\w*|фото|fullscreen|image|picture)",
        "render_graph": r"(?:график\w*|диаграмм\w*|3d|ракурс|масштаб|wave|graph|chart)",
        "render_table": r"(?:таблиц\w*|table)",
        "render_code": r"(?:код\w*|code|copy block)",
        "render_file": r"(?:файл\w*|документ\w*|скача\w*|download|file)",
        "render_diagram_link_video": r"(?:схем\w*|диаграмм\w*|ссылк\w*|link|diagram|video\s+block|видео\s+в\s+ответе|видеоблок)",
    }
    chosen = []
    for screen in APRIL_UI_SCREEN_REGISTRY.get("screens", []):
        screen_id = str(screen.get("id") or "")
        route = str(screen.get("route") or "")
        if unresolved_ui_control and not full:
            continue
        if screen_id.startswith("render_") and not full:
            pattern = renderer_query_patterns.get(screen_id, r"(?!)")
            if not re.search(pattern, query, re.I):
                continue
        if screen_id == "chat_attachment_picker" and not full and "attachments" not in selected_area_ids:
            continue
        if screen_id == "chat_free_media_limit_dialog" and not full and not re.search(r"(?:лимит\w*|quota|invite link|дополнительн\w* операц)", query, re.I):
            continue
        if full or route in routes or (route == "inside a chat answer" and "/" in routes) or (route == "overlay on chat /" and "/" in routes):
            chosen.append(dict(screen))
    return {
        "schema": APRIL_UI_SCREEN_REGISTRY["schema"],
        "visual_evidence_mode": APRIL_UI_SCREEN_REGISTRY["visual_evidence_mode"],
        "source": APRIL_UI_SCREEN_REGISTRY["source"],
        "screens": chosen[:24],
        "screen_count": len(chosen),
        "full_inventory": bool(full),
        "source_limit": "Архив исходников подтверждает структуру компонентов и обработчики, но не является снимком текущего production-экрана.",
    }


def _select_user_journeys(query: str) -> list[dict]:
    """Return a small relevant workflow excerpt without guessing unseen UI controls."""
    low = _text(query).lower().replace("ё", "е")
    if _is_external_community_topic(low):
        return []
    assistant_owned_content = bool(re.search(
        r"(?:\b(?:тво[её]|ваш|ваше|мой|мое|моё|наш|наше)\s+(?:ответ|сообщен\w*)|"
        r"\bответ\w*\s+(?:април\w*|april)\b|\bсообщен\w*\s+(?:април\w*|april)\b|"
        r"\b(?:your|my|our)\s+(?:april\s+)?(?:reply|response|message)\b|\bapril(?:'s)?\s+(?:reply|response|message)\b)",
        low, re.I,
    ))
    public_post_intent = bool(re.search(r"(?:отправ\w*|пересыл\w*|опубликов\w*|публикац\w*|размест\w*|post\w*|publish\w*|send\w*)", low, re.I)) and bool(re.search(r"(?:сообществ\w*|community)", low, re.I))
    if assistant_owned_content and public_post_intent:
        journey = APRIL_USER_JOURNEYS.get("response-share-community")
        return [{"id": "response-share-community", **journey}] if isinstance(journey, dict) else []
    result = []
    feedback_target = bool(re.search(r"(?:отблагодар\w*|поблагодар\w*|спасибо.{0,45}(?:кноп|наж|где|куда)|пожалова\w*|жалоб\w*|feedback\s+button|report\s+(?:button|response))", low, re.I))
    feedback_location = bool(re.search(r"(?:куда.{0,40}наж|где.{0,70}(?:кноп|наход|это)|кноп\w*.{0,60}(?:под\s+(?:ответ|сообщ)|где|наж)|покажи.{0,60}(?:где|куда|путь)|where.{0,60}(?:click|button|find))", low, re.I | re.S))
    if feedback_target and feedback_location and not re.search(r"(?:создай|сгенерир\w*|построй|нарисуй|напиши|generate|create|build|write).{0,60}(?:график|код|картинк|изображени|graph|code|image)", low, re.I | re.S):
        journey = APRIL_USER_JOURNEYS.get("response-feedback")
        return [{"id": "response-feedback", **journey}] if isinstance(journey, dict) else []
    if re.search(r"(?:создай|сгенерируй|нарисуй|изобрази)\s+(?:мне\s+)?(?:нов\w*\s+)?(?:картинк\w*|изображени\w*|иллюстраци\w*|\bimage\b|\bpicture\b)", low, re.I):
        return []
    if "_is_attachment_instruction_query" in globals() and _is_attachment_instruction_query(query):
        journey = APRIL_USER_JOURNEYS.get("attach_image")
        if isinstance(journey, dict):
            result.append({"id": "attach_image", **journey})
    existing_ids = {str(item.get("id")) for item in result if isinstance(item, dict)}
    for journey_id, journey in APRIL_USER_JOURNEYS.items():
        if journey_id in existing_ids:
            continue
        aliases = journey.get("aliases", [])
        if any(str(alias).lower().replace("ё", "е") in low for alias in aliases):
            result.append({"id": journey_id, **journey})
            existing_ids.add(journey_id)
    if not result:
        ids = [area_id for score, area_id in _semantic_site_area_scores(low) if score >= 2.0]
        mapping = {"attachments":"attach_image", "image-controls":"download_image", "history":"resume_history", "settings":"profile_language_plan", "space":"community", "guide":"get_help", "help-center":"get_help", "how-to-use":"get_help"}
        for area_id in ids:
            if area_id == "attachments" and not ("_is_attachment_instruction_query" in globals() and _is_attachment_instruction_query(query)):
                continue
            if area_id == "image-controls" and not re.search(r"(?:скача\w*|сохран\w*|поделит\w*|download|save|share)", low):
                continue
            if area_id == "space" and not re.search(r"(?:сообществ|community|пользоват|участник|друз|контакт|личн\w*\s+чат|private chat)", low):
                continue
            if area_id == "history" and not re.search(r"(?:истори|сохраненн\w*|стар\w*\s+диалог|предыдущ\w*\s+разговор|continue this dialogue|saved dialogues)", low):
                continue
            if area_id == "settings" and not re.search(r"(?:профил|кабинет|настройк|язык|april id|premium id|тариф|подписк|аккаунт|settings)", low):
                continue
            journey_id = mapping.get(area_id)
            if journey_id and journey_id in APRIL_USER_JOURNEYS and APRIL_USER_JOURNEYS[journey_id] not in result:
                result.append({"id": journey_id, **APRIL_USER_JOURNEYS[journey_id]})
    return result[:3]


